import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;

/** Card approvals arrive in UTC; settlement and partner statements use the KST calendar date. */
public class BusinessDateResolver {
    private final ZoneId zone;

    public BusinessDateResolver(ZoneId zone) {
        this.zone = zone;
    }

    public LocalDate dateOf(Instant approvedAt) {
        return approvedAt.atZone(zone).toLocalDate();
    }
}
package util;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/** KRW arithmetic shared by settlement and reporting. */
public final class Money {
    private static final BigDecimal TEN_THOUSAND = BigDecimal.valueOf(10_000);

    private Money() {}

    /** foreign amount x rate / unit, rounded to whole won (acquirer contract: half-up). */
    public static long toKrw(BigDecimal amount, BigDecimal rate, int unit) {
        return amount.multiply(rate)
                .divide(BigDecimal.valueOf(unit), 0, RoundingMode.HALF_UP)
                .longValueExact();
    }

    /** Commission on gross KRW; partner contract truncates fractional won. */
    public static long fee(long grossKrw, int feeBps) {
        if (grossKrw <= 0 || feeBps <= 0) return 0;
        return BigDecimal.valueOf(grossKrw)
                .multiply(BigDecimal.valueOf(feeBps))
                .divide(TEN_THOUSAND, 0, RoundingMode.DOWN)
                .longValueExact();
    }

    public static String won(long krw) {
        DecimalFormat f = new DecimalFormat("#,##0", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(krw);
    }

    public static String rate(BigDecimal rate) {
        DecimalFormat f = new DecimalFormat("#,##0.00", DecimalFormatSymbols.getInstance(Locale.ROOT));
        return f.format(rate);
    }
}
package service;

import java.util.Map;

/** Maps a card currency to the vendor pair code and its quotation unit. */
public final class CurrencyPairs {
    private static final Map<String, Integer> UNITS = Map.of("USD", 1, "EUR", 1, "JPY", 100, "CNY", 1);

    private CurrencyPairs() {}

    public static String pairOf(String currency) {
        requireSupported(currency);
        return currency + "KRW";
    }

    /** JPY is quoted per 100 yen. */
    public static int unitOf(String currency) {
        requireSupported(currency);
        return UNITS.get(currency);
    }

    public static boolean supported(String currency) {
        return UNITS.containsKey(currency);
    }

    private static void requireSupported(String currency) {
        if (!supported(currency)) throw new IllegalArgumentException("unsupported currency " + currency);
    }
}
